if signoff:
 for x in items:
  x['review']='Collection review and approved revisions signed off by Alex Ehsan, MD, PhD'
  x['review_date']=signoff['date']
 Path('data/illustrated-posters.json').write_text(json.dumps(items,ensure_ascii=False,indent=2))
esc=html.escape
